import 'package:flutter/material.dart';
import '../../data/repositories/promotion_repository.dart';
import '../../domain/models/promotion_model.dart';
import 'promotion_form_screen.dart';
class PromotionDetailScreen extends StatefulWidget {const PromotionDetailScreen({required this.repository, required this.promotionId, super.key}); final PromotionRepository repository; final String promotionId; @override State<PromotionDetailScreen> createState()=>_PromotionDetailScreenState();}
class _PromotionDetailScreenState extends State<PromotionDetailScreen>{PromotionModel? _p; bool _loading=true; @override void initState(){super.initState();_load();} Future<void> _load() async{setState(()=>_loading=true);_p=await widget.repository.getById(widget.promotionId);if(mounted)setState(()=>_loading=false);} @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Detalle promoción'),actions:[IconButton(onPressed:() async{final ok=await Navigator.push(context,MaterialPageRoute(builder:(_)=>PromotionFormScreen(repository: widget.repository,promotionId: widget.promotionId)));if(ok==true)_load();},icon:const Icon(Icons.edit)),IconButton(onPressed:() async{await widget.repository.toggle(widget.promotionId);_load();},icon:const Icon(Icons.toggle_on)),IconButton(onPressed:() async{final ok=await showDialog<bool>(context: context,builder:(_)=>AlertDialog(title:const Text('Archivar promoción'),content:const Text('¿Confirmar?'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancelar')),FilledButton.tonal(onPressed:()=>Navigator.pop(context,true),child:const Text('Archivar'))]));if(ok==true){await widget.repository.archive(widget.promotionId);if(mounted)Navigator.pop(context,true);}},icon:const Icon(Icons.delete_outline))]),body:_loading?const Center(child:CircularProgressIndicator()):Padding(padding:const EdgeInsets.all(16),child:Text('${_p?.name}\nTipo: ${_p?.type}\nActiva: ${_p?.isActive==true?'Sí':'No'}\n${_p?.description ?? ''}')));
}
